	return (To + TargetVelocity * Seconds).GetSafeNormal();
}

TArray<FVector2D> JamBossRules::VolleyDirections(const FVector2D& AimDir, int32 Count, float SpreadDeg)
{
	TArray<FVector2D> Directions;
	const FVector2D Dir = AimDir.GetSafeNormal();
	for (int32 Index = 0; Index < Count; ++Index)
	{
		const float Angle = Count > 1 ? SpreadDeg * (static_cast<float>(Index) / (Count - 1) - 0.5f) : 0.f;
		Directions.Add(Dir.GetRotated(Angle));
	}
	return Directions;
}

void JamBossRules::Act(FJamFight& Fight, const FJamIntent& Intent, const FJamBalanceData& Balance)
{
	// The finisher of the stolen katana ends with the same pause as his own attacks: the player's opening.
	const FJamKatanaState& Katana = Fight.Fighters[EJamSide::Boss].Katana;
	if (Katana.bHitPending && JamKatanaRules::IsFinisher(Katana.Strike))
	{
		const int32 RestUntil = Katana.HitTick + JamSim::Ticks(Balance.BossRecovery);
		Fight.Boss.BusyUntilTick = FMath::Max(Fight.Boss.BusyUntilTick, RestUntil);
	}
	if (IsBusy(Fight))
	{
		return;
	}
	if (Intent.bSlam && Fight.Tick >= Fight.Boss.SlamReadyTick)
	{
		StartSlam(Fight, Intent.Aim.Point, Balance);
	}
	else if (Intent.bVolley && Fight.Tick >= Fight.Boss.VolleyReadyTick)
	{
		StartVolley(Fight, Balance);
	}
}
#include "Sim/JamParryRules.h"

bool JamParryRules::CanStart(const FJamParryState& State, int32 Tick)
{
	return Tick >= State.ReadyTick;
}

FJamParryState JamParryRules::Start(int32 Tick, const FJamBalanceData& Balance)
{
	FJamParryState State;
	State.ActiveUntilTick = Tick + JamSim::Ticks(Balance.ParryWindow);
	// A cooldown shorter than the window would let a held key keep the window open for ever.
	State.ReadyTick = FMath::Max(State.ActiveUntilTick, Tick + JamSim::Ticks(Balance.ParryCooldown));
	return State;
}

bool JamParryRules::IsActive(const FJamParryState& State, int32 Tick)
{
	return Tick < State.ActiveUntilTick;
}

bool JamParryRules::ShotInReach(const FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	const FJamFighter& Me = Fight.Fighters[Side];
	for (const FJamProjectile& Flying : Fight.Projectiles)
	{
		if (Flying.Owner == Side)
		{
			continue;
		}
		// Where the shot passes during one window: if that path touches the body, a parry opened now catches it.
		const FVector2D Closest = FMath::ClosestPointOnSegment2D(Me.Pos, Flying.Pos, Flying.Pos + Flying.Vel * Balance.ParryWindow);
		if (FVector2D::Distance(Closest, Me.Pos) <= Me.Radius + Flying.Radius)
		{
			return true;
		}
	}
	return false;
}

void JamParryRules::Deflect(FJamProjectile& Projectile, const FVector2D& FormerOwnerPos, int32 Tick, const FJamBalanceData& Balance)
{
	FVector2D Dir = (FormerOwnerPos - Projectile.Pos).GetSafeNormal();
	if (Dir.IsNearlyZero())
	{
		Dir = -Projectile.Vel.GetSafeNormal();
	}
	Projectile.Owner = JamSim::Other(Projectile.Owner);
	Projectile.Vel = Dir * Balance.ParryReturnSpeed;
	Projectile.Damage *= Balance.ParryDamageScale;
	Projectile.DieTick = Tick + JamSim::Ticks(Balance.ParryReturnLife);
}
#include "Sim/JamUltimateRules.h"

#include "Sim/JamFightOps.h"
#include "Sim/JamLoadoutRules.h"

bool JamUltimateRules::OnLine(
	const FVector2D& Origin, const FVector2D& Dir, const FVector2D& TargetPos, float TargetRadius, float Range, float HalfWidth)
{
	const FVector2D Along = Dir.GetSafeNormal();
	const FVector2D ToTarget = TargetPos - Origin;
	const double Forward = FVector2D::DotProduct(ToTarget, Along);
	const double Sideways = FMath::Abs(FVector2D::CrossProduct(Along, ToTarget));
	return Forward >= -TargetRadius && Forward <= Range + TargetRadius && Sideways <= HalfWidth + TargetRadius;
}

void JamUltimateRules::Charge(FJamFight& Fight, const FJamBalanceData& Balance)
{
	const bool bWasFull[] = { Fight.Fighters[EJamSide::Hero].Ultimate.Meter >= 1.f, Fight.Fighters[EJamSide::Boss].Ultimate.Meter >= 1.f };
	for (const FJamEvent& Event : Fight.Events)
	{
		if (Event.Type == EJamEvent::Hit)
		{
			FJamUltimateState& Ultimate = Fight.Fighters[JamSim::Other(Event.Side)].Ultimate;
			Ultimate.Meter = FMath::Min(1.f, Ultimate.Meter + Event.Amount * Balance.UltimateGainPerDamage);
		}
	}
	// Announced after the loop: a new event would move the array the loop walks.
	for (const EJamSide Side : { EJamSide::Hero, EJamSide::Boss })
	{
		const FJamFighter& Self = Fight.Fighters[Side];
		if (!bWasFull[static_cast<int32>(Side)] && Self.Ultimate.Meter >= 1.f)
		{
			JamFightOps::AddEvent(Fight, EJamEvent::UltimateReady, Side, 0, Self.Pos, 0.f);
		}
	}
}

void JamUltimateRules::Press(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	FJamUltimateState& Ultimate = Self.Ultimate;
	const bool bOwns = JamLoadoutRules::ActionFor(EJamButton::Ultimate, Side, Fight.Ledger) == EJamAction::Ultimate;
	if (!bOwns || Ultimate.bPending || Ultimate.Meter < 1.f)
	{
		return;
	}
	Ultimate.bPending = true;
	Ultimate.SlashTick = Fight.Tick + JamSim::Ticks(Balance.UltimateWindUp);
	Ultimate.Dir = Self.Facing.GetSafeNormal();
	JamFightOps::AddEvent(Fight, EJamEvent::UltimateStarted, Side, 0, Self.Pos, 0.f);
}

void JamUltimateRules::Land(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	FJamUltimateState& Ultimate = Self.Ultimate;
	if (!Ultimate.bPending || Fight.Tick < Ultimate.SlashTick)
	{
		return;
	}
	Ultimate.bPending = false;
	Ultimate.Meter = 0.f;
	const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Ultimate.Dir.Y, Ultimate.Dir.X));
	JamFightOps::AddEvent(Fight, EJamEvent::UltimateSlash, Side, 0, Self.Pos, static_cast<float>(Yaw));
	const EJamSide TargetSide = JamSim::Other(Side);
	const FJamFighter& Target = Fight.Fighters[TargetSide];
	if (OnLine(Self.Pos, Ultimate.Dir, Target.Pos, Target.Radius, Balance.UltimateRange, Balance.UltimateHalfWidth))
	{
		JamFightOps::Hurt(Fight, TargetSide, Balance.UltimateDamage, Target.Pos, SlashId);
	}
}
