IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamComboOwnedTest, "Jam.Combo.OnlyWhatHeStole", JamTest::Flags)

bool FJamComboOwnedTest::RunTest(const FString& Parameters)
{
