268	void AJamEffectsView::DrawCircles(const FJamFight& Fight, float Alpha, float Time)
269	{
270		DrawCash(Fight, Alpha, Time);
271		if (Fight.Phase == EJamPhase::Fight || Fight.Phase == EJamPhase::Stunned)
272		{
273			DrawLane(Fight, EJamSide::Hero, Alpha);
274			DrawLane(Fight, EJamSide::Boss, Alpha);
275		}
276		// Fight.Tick is the step to come: the picture is between the two before it.
277		const float Tick = Fight.Tick - 1.f + Alpha;
278		for (const FJamHazard& Hazard : Fight.Hazards)
279		{
280			DrawDisc(Hazard.Pos, Hazard.Radius, CircleHeight, CircleColor);
281			// The fill grows to the edge of the circle exactly when it hits: the player reads the time left from it.
282			DrawDisc(Hazard.Pos, Hazard.Radius * JamHazardRules::Progress(Hazard, Tick), FillHeight, FillColor);
283		}
284		for (const FJamFighter& Fighter : Fight.Fighters.Items)
285		{
286			if (Fighter.Ultimate.bPending)
287			{
288				DrawDisc(FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha)), Fighter.Radius * ChargeRingScale, CircleHeight,
289					UltimateColor);
290			}
291			const FJamParryState& Parry = Fighter.Parry;
292			const FVector2D SelfPos = FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha));
293			if (JamParryRules::IsRaising(Parry, Fight.Tick - 1))
294			{
295				// The Publisher's stance going up (T-038): the warning before it sends anything back.
296				const float Rise = 1.f - (Parry.ActiveFromTick - Tick) / ParryRaiseTicks;
297				DrawShield(SelfPos, Fighter.Radius * JamFeedbackRules::ParryRingScale(1.f, Feedback), Rise);
298			}
299			else if (JamParryRules::IsActive(Parry, Fight.Tick - 1))
300			{
301				const float WindowLeft = (Parry.ActiveUntilTick - Tick) / FMath::Max(1, Parry.ActiveUntilTick - Parry.ActiveFromTick);
302				DrawShield(SelfPos, Fighter.Radius * JamFeedbackRules::ParryRingScale(WindowLeft, Feedback));
303			}
304		}
305		const FJamBossState& Chain = Fight.Boss;
306		if (Chain.Combo != EJamCombo::None && !Chain.Links.IsEmpty() && Tick < Chain.Links[0].Tick)
307		{
308			// T-056: the tell of a chain, a ring that turns under him before the first link.
309			const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];
310			DrawRing(FMath::Lerp(Boss.PrevPos, Boss.Pos, static_cast<double>(Alpha)), Boss.Radius * ComboTellScale, BossBladeColor, Time);
311		}
312		if (bUltimateReady)
313		{
314			const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
315			DrawRing(FMath::Lerp(Hero.PrevPos, Hero.Pos, static_cast<double>(Alpha)), Hero.Radius * ChargeRingScale, UltimateColor, Time);
316		}
317		for (const FJamProjectile& Projectile : Fight.Projectiles)
