	Turn[EJamSide::Boss].Aim.Dir = FVector2D(0.0, 1.0);
	JamTest::Run(F, Turn, B, 5);
	TestTrue(TEXT("his line does not follow his aim"), F.Fighters[EJamSide::Boss].Ultimate.Dir.Equals(FVector2D(-1.0, 0.0), 1e-6));
	return true;
}

