62	IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamUltimateBossLockedTest, "Jam.Ultimate.BossLineStaysLocked", JamTest::Flags)
63	
64	bool FJamUltimateBossLockedTest::RunTest(const FString& Parameters)
65	{
66		const FJamBalanceData B = JamTest::Balance();
67		FJamFight F = JamTest::Fight(B, FVector2D(-600.0, 0.0), FVector2D::ZeroVector);
68		JamLoadoutRules::Give(F.Ledger, EJamMechanic::Ultimate, EJamSide::Boss);
69		F.Fighters[EJamSide::Boss].Ultimate.Meter = 1.f;
70		// Past his opening pause: he may press at once.
71		F.Boss.BusyUntilTick = 0;
72		FJamIntents Press;
73		Press[EJamSide::Boss].Aim.Dir = FVector2D(-1.0, 0.0);
74		Press[EJamSide::Boss].bUltimate = true;
75		JamFightRules::Step(F, Press, B);
76		FJamIntents Turn;
77		Turn[EJamSide::Boss].Aim.Dir = FVector2D(0.0, 1.0);
78		JamTest::Run(F, Turn, B, 5);
79		TestTrue(TEXT("he pressed"), F.Fighters[EJamSide::Boss].Ultimate.bPending);
80		TestTrue(TEXT("his line does not follow his aim"), F.Fighters[EJamSide::Boss].Ultimate.Dir.Equals(FVector2D(-1.0, 0.0), 1e-6));
81		return true;
82	}
83	
84	#endif
